// The data script is generated by the same run as the ranked board.
const data = window.RADAR;
const $ = (s) => document.querySelector(s);
const esc = (v) => String(v ?? '—').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => n == null ? '—' : '$' + (n >= 1e9 ? (n/1e9).toFixed(2)+'B' : n >= 1e6 ? (n/1e6).toFixed(2)+'M' : Math.round(n).toLocaleString());
const pct = n => n == null ? '—' : (n > 0 ? '+' : '') + n.toFixed(2) + '%';
const x = n => n.toFixed(4) + '×';
const state = {status:'early', sort:'rank', direction:1, selected:null};
const params = new URLSearchParams(location.search);
if (params.get('view') === 'live') state.status = 'live';
if (params.get('category')) $('#category').dataset.initial = params.get('category');
if (params.get('slug')) state.selected = params.get('slug');
$('#date').textContent = data.as_of;
$('#total').textContent = data.rows.length;
$('#watch').textContent = data.watchlist_size;
const all = [...data.rows,...data.live];
for (const [selector, values] of [['#category', all.map(r=>r.category || 'Unclassified')], ['#chain', all.flatMap(r=>r.chains)]]) {
  for (const value of [...new Set(values)].sort()) $(selector).add(new Option(value,value));
}
if ($('#category').dataset.initial) $('#category').value = $('#category').dataset.initial;
function filtered() {
  const q = $('#search').value.trim().toLowerCase(), category = $('#category').value, chain = $('#chain').value, tvl = $('#tvl').value, growth = $('#growth').value;
  return (state.status === 'early' ? data.rows : data.live).filter(r => (!q || [r.name,r.slug,r.category,...r.chains].join(' ').toLowerCase().includes(q)) && (!category || (r.category || 'Unclassified') === category) && (!chain || r.chains.includes(chain)) && (!tvl || (tvl==='small' ? r.tvl_usd<5e7 : tvl==='mid' ? r.tvl_usd>=5e7 && r.tvl_usd<1e9 : r.tvl_usd>=1e9)) && (!growth || (growth==='missing' ? r.change_7d==null : r.change_7d!=null && (growth==='up' ? r.change_7d>0 : r.change_7d<0)))).sort((a,b)=>{
    const av=a[state.sort], bv=b[state.sort]; if(av==null)return 1;if(bv==null)return -1;
    return (typeof av==='string' ? av.localeCompare(bv) : av-bv)*state.direction || a.name.localeCompare(b.name);
  });
}
function detail(r) {
  if (!r) { $('#detail').innerHTML='<div class="label">PROTOCOL DETAIL</div><h3>No selection</h3><p class="sub">Change the filters to see a protocol.</p>'; return; }
  const isEarly=state.status==='early', m=r.model;
  $('#detail').innerHTML = `<div class="label">${isEarly?'PROTOCOL DETAIL / '+String(r.rank).padStart(3,'0'):'TOKEN RECORD'}</div><h3>${esc(r.name)}</h3><div class="sub">${esc(r.category || 'Unclassified')} · ${esc(r.chains.join(', ') || 'Chain not reported')}</div><div class="badge">${isEarly ? esc(r.confidence.toUpperCase())+' CONFIDENCE' : 'TOKEN RECORDED'}</div><div class="label">${isEarly?'IMPLIED VALUE':'RECORDED MARKET CAP'}</div><div class="detail-value">${money(r.implied_value_usd)}</div><div class="explain">${isEarly?'A modeled scenario, not a token price.':'Market cap from the snapshot; unavailable when not reported.'}</div>${isEarly ? `<div class="calc"><div class="label">THE ARITHMETIC</div><div class="calc-row"><span>TVL</span><b>$${r.tvl_usd.toLocaleString()}</b></div><div class="calc-row"><span>Category median (${m.peer_count} peers)</span><b>${x(m.multiple)}</b></div><div class="calc-row"><span>Momentum (${pct(r.change_7d)})</span><b>${x(m.momentum)}</b></div><div class="calc-row"><span>Maturity (${r.age_days==null?'365d fallback':r.age_days+'d'})</span><b>${x(m.maturity)}</b></div><div class="calc-row"><span>Breadth (${r.chains.length} chains)</span><b>${x(m.breadth)}</b></div><div class="calc-row"><span>Rounded result</span><b>$${r.implied_value_usd.toLocaleString()}</b></div></div><h4>FIELD PLAN / ESTIMATES</h4><ol>${r.farm_steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>` : `<div class="calc"><div class="calc-row"><span>TVL</span><b>${money(r.tvl_usd)}</b></div><div class="calc-row"><span>7-day change</span><b>${pct(r.change_7d)}</b></div><div class="calc-row"><span>Symbol</span><b>${esc(r.symbol)}</b></div><div class="calc-row"><span>Listed</span><b>${esc(r.listed_at)}</b></div></div>`}`;
}
function render() {
  document.querySelectorAll('[data-status]').forEach(b=>b.classList.toggle('active',b.dataset.status===state.status));
  const rows=filtered(); if (!rows.some(r=>r.slug===state.selected)) state.selected=rows[0]?.slug || null;
  $('#count').textContent=`/ ${rows.length} RESULTS`;
  $('#shown').textContent=`${rows.length} RECORDS · ${state.status==='early'?'RANKED BY MODEL':'MARKET CAP VIEW'}`;
  $('#empty').hidden=rows.length>0;
  $('#rows').innerHTML=rows.map(r=>`<tr class="data ${r.slug===state.selected?'selected':''}" data-slug="${esc(r.slug)}"><td class="rank">${r.rank ? String(r.rank).padStart(3,'0') : '—'}</td><td class="name">${esc(r.name)}<small>${esc(r.category || 'Unclassified')} · ${esc(r.chains[0] || 'No chain')}</small></td><td>${money(r.tvl_usd)}</td><td class="${r.change_7d>0?'positive':r.change_7d<0?'negative':''}">${pct(r.change_7d)}</td><td class="value">${money(r.implied_value_usd)}</td><td class="arrow">↗</td></tr>`).join('');
  detail(rows.find(r=>r.slug===state.selected));
}
$('#rows').addEventListener('click',e=>{const row=e.target.closest('tr[data-slug]');if(row){state.selected=row.dataset.slug;render();}});
document.querySelectorAll('[data-status]').forEach(b=>b.addEventListener('click',()=>{state.status=b.dataset.status;state.sort=state.status==='early'?'rank':'implied_value_usd';state.direction=state.status==='early'?1:-1;state.selected=null;render();}));
document.querySelectorAll('[data-sort]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.sort;state.direction=state.sort===key?-state.direction:(key==='name'||key==='rank'?1:-1);state.sort=key;render();}));
document.querySelectorAll('input,select').forEach(el=>el.addEventListener('input',render));
$('#reset').addEventListener('click',()=>{document.querySelectorAll('input,select').forEach(el=>el.value='');render();});
render();
